#!/usr/bin/env bash
# GSZ step131 — Report a problem / request a replacement, from the customer
# dashboard. New: routes/issues.js (+/account/support page), routes/adminIssues.js
# (+/admin/issues manage page), order_issues table. Patches: server.js (2 mounts),
# account dashboard (support link). Owner gets a best-effort WhatsApp alert.
# Safe + idempotent; restores on any failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step131-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/account/dashboard.ejs)
NEW=(routes/issues.js routes/adminIssues.js views/account/support.ejs views/admin/issues.ejs)
echo "==> step131: report issue / replacement"
mkdir -p "$BK"
for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"
mkdir -p "$GSZ/routes" "$GSZ/views/account" "$GSZ/views/admin"
echo ""  | base64 -d > "$GSZ/routes/issues.js"
echo ""   | base64 -d > "$GSZ/routes/adminIssues.js"
echo "" | base64 -d > "$GSZ/views/account/support.ejs"
echo "" | base64 -d > "$GSZ/views/admin/issues.ejs"
echo ""   | base64 -d > "$TMP/p.js"
echo ""     | base64 -d > "$TMP/m.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"
for f in server.js routes/issues.js routes/adminIssues.js; do node --check "$GSZ/$f"; done
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/account/dashboard.ejs','views/account/support.ejs','views/admin/issues.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step131 OK ✅  Customers can now report a problem / request a replacement from their account (new 'Report a problem' link, page /account/support). Manage them at /admin/issues — you also get a best-effort WhatsApp alert on each report."
